const panelMotion = { initial: { opacity: 0, y: 10 }, animate: { opacity: 1, y: 0 }, transition: { duration: .28 } };

function Panel({ children, className = "" }: { children: React.ReactNode; className?: string }) {
  return <motion.section {...panelMotion} className={`panel ${className}`}>{children}</motion.section>;
}

function PageHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="mono text-[10px] uppercase tracking-[.18em] text-[#f2f2f2]">{eyebrow}</p><h1 className="mt-2 text-3xl font-semibold tracking-[-.055em] sm:text-4xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-[#8b8b8b]">{description}</p></div>{action && <div className="shrink-0">{action}</div>}</div>;
}

function Pill({ children, tone = "violet" }: { children: React.ReactNode; tone?: "violet" | "green" | "amber" | "cyan" | "gray" }) {
  const colors = { violet: "border-[#f2f2f2]/25 bg-[#f2f2f2]/10 text-[#d0d0d0]", green: "border-[#d0d0d0]/25 bg-[#d0d0d0]/[.08] text-[#e0e0e0]", amber: "border-[#9a9a9a]/25 bg-[#9a9a9a]/[.08] text-[#c2c2c2]", cyan: "border-[#bdbdbd]/25 bg-[#bdbdbd]/[.08] text-[#c7c7c7]", gray: "border-white/10 bg-white/[.035] text-[#9c9c9c]" };
  return <span className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[11px] font-medium ${colors[tone]}`}>{children}</span>;
}

function Progress({ value, color = "#f2f2f2" }: { value: number; color?: string }) {
  return <div className="h-1.5 overflow-hidden rounded-full bg-white/[.07]" role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={value}><div className="h-full rounded-full transition-all" style={{ width: `${Math.max(0, Math.min(100, value))}%`, background: color }} /></div>;
}

function MetricCard({ icon: Icon, label, value, note, tone = "violet" }: { icon: typeof Activity; label: string; value: string; note: string; tone?: "violet" | "green" | "amber" | "cyan" }) {
  const colors = { violet: "bg-[#f2f2f2]/10 text-[#d2d2d2]", green: "bg-[#d0d0d0]/10 text-[#d0d0d0]", amber: "bg-[#9a9a9a]/10 text-[#9a9a9a]", cyan: "bg-[#bdbdbd]/10 text-[#bdbdbd]" };
  return <Panel className="p-4"><div className={`grid size-9 place-items-center rounded-lg ${colors[tone]}`}><Icon className="size-4"/></div><p className="mono mt-5 text-2xl font-semibold tracking-[-.04em]">{value}</p><p className="mt-1 text-xs text-[#838383]">{label}</p><p className="mt-3 text-[10px] text-[#c0c0c0]">{note}</p></Panel>;
}

function number(value: number) { return new Intl.NumberFormat("en-IN").format(Math.round(value)); }
function dateLabel(value: string) { return new Intl.DateTimeFormat("en", { month: "short", day: "numeric", year: "numeric" }).format(new Date(value)); }
function shortDate(value: string) { return new Intl.DateTimeFormat("en", { month: "short", day: "numeric" }).format(new Date(value)); }
function initials(value: string) { return value.split(/\s+/).map((part) => part[0]).join("").slice(0, 2).toUpperCase(); }
function recordsOf(sessions: ReturnType<typeof useSprintly>["sessions"]): SprintlySession[] { return sessions.map((session) => session.record); }
function avatarStyle(archetype: string, traits: string[]) {
  const seed = `${archetype}:${traits.join(":")}`;
  const palettes = ["from-[#f2f2f2] to-[#bdbdbd]", "from-[#9a9a9a] to-[#b7b7b7]", "from-[#d0d0d0] to-[#bdbdbd]", "from-[#d2d2d2] to-[#9a9a9a]"];
  return palettes[seed.length % palettes.length];
}

function dateRangeTitle(range: DateRange) {
  return range === "today" ? "Today" : range === "week" ? "This week" : range === "month" ? "This month" : range === "custom" ? "Custom range" : "All time";
}

function summarize(records: SprintlySession[]) {
  const aggregate = aggregateSessions(records);
  return { aggregate, failures: aggregate.reliability.failures, recovery: aggregate.reliability.recoveryRate };
}

function ImportFlow({ open, onClose }: { open: boolean; onClose: () => void }) {
  const { sessions, importSessions } = useSprintly();
  const inputRef = useRef<HTMLInputElement>(null);
  const [validation, setValidation] = useState<ImportValidation | null>(null);
  const [fileName, setFileName] = useState("");
  const [reading, setReading] = useState(false);
  if (!open) return null;
  const existingIds = new Set(sessions.map((session) => session.record.sessionId));
  const preview = validation ? summarize(validation.sessions) : null;
  const chooseFile = async (file: File | undefined) => {
    if (!file) return;
    setFileName(file.name);
    // Reject oversized selections before reading them into memory.
    if (!isSupportedImportFileSize(file.size)) {
      setValidation({ ok: false, sessions: [], duplicates: [], issues: [{ index: -1, message: `"${file.name}" is too large (${Math.ceil(file.size / 1_000_000)} MB). Choose an export under ${Math.floor(MAX_IMPORT_FILE_BYTES / 1_000_000)} MB.` }], contract: SPRINTLY_CONTRACT });
      return;
    }
    setReading(true);
    setValidation(parseSprintlyImportText(await file.text(), existingIds));
    setReading(false);
  };
  const close = () => { setValidation(null); setFileName(""); onClose(); };
  const confirm = () => { if (!validation?.sessions.length || validation.issues.length) return; importSessions(validation.sessions); close(); };
  return <div className="fixed inset-0 z-[120] grid place-items-center bg-black/75 p-4 backdrop-blur-sm"><div role="dialog" aria-modal="true" aria-labelledby="import-title" className="max-h-[90dvh] w-full max-w-2xl overflow-y-auto rounded-2xl border border-white/10 bg-[#141414] shadow-2xl"><div className="flex items-start justify-between border-b border-white/[.07] p-5 sm:p-6"><div><p className="mono text-[10px] uppercase tracking-[.18em] text-[#bdbdbd]">Explicit handoff · Sprintly session v1</p><h2 id="import-title" className="mt-2 text-xl font-semibold">Import Sprintly Data</h2><p className="mt-2 text-xs leading-5 text-[#858585]">Choose an extension JSON export. Nothing enters your history until you confirm this preview.</p></div><button onClick={close} aria-label="Close import dialog" className="grid size-10 place-items-center rounded-lg text-[#7a7a7a] hover:bg-white/[.05]"><X className="size-4"/></button></div><div className="space-y-4 p-5 sm:p-6"><input ref={inputRef} type="file" accept=".json,application/json" className="sr-only" onChange={(event) => void chooseFile(event.target.files?.[0])}/><button onClick={() => inputRef.current?.click()} className="flex min-h-[132px] w-full flex-col items-center justify-center rounded-xl border border-dashed border-white/[.16] bg-white/[.02] text-sm text-[#c1c1c1] hover:bg-white/[.04]"><FileJson className="mb-3 size-6 text-[#d6d6d6]"/>{reading ? "Reading export…" : fileName || "Select a .json export"}<span className="mt-2 text-[10px] text-[#777777]">Local file access is limited to this explicit selection.</span></button>{validation && <>{preview && <div className="grid grid-cols-2 gap-2 sm:grid-cols-4"><div className="rounded-xl border border-white/[.07] bg-white/[.025] p-3"><p className="mono text-lg font-semibold">{validation.sessions.length}</p><p className="text-[10px] text-[#7d7d7d]">sessions ready</p></div><div className="rounded-xl border border-white/[.07] bg-white/[.025] p-3"><p className="mono text-lg font-semibold">{formatDuration(preview.aggregate.activeDurationSeconds)}</p><p className="text-[10px] text-[#7d7d7d]">coding time</p></div><div className="rounded-xl border border-white/[.07] bg-white/[.025] p-3"><p className="mono text-lg font-semibold">{preview.aggregate.coding.manualPercent}%</p><p className="text-[10px] text-[#7d7d7d]">manual</p></div><div className="rounded-xl border border-white/[.07] bg-white/[.025] p-3"><p className="mono text-lg font-semibold">{preview.recovery}%</p><p className="text-[10px] text-[#7d7d7d]">recovery</p></div></div>}{validation.issues.length > 0 && <div className="rounded-xl border border-[#b7b7b7]/25 bg-[#b7b7b7]/[.06] p-4"><p className="text-sm font-medium text-[#bdbdbd]">{validation.issues.length} record{validation.issues.length === 1 ? "" : "s"} rejected</p><ul className="mt-2 space-y-1 text-xs leading-5 text-[#9f9f9f]">{validation.issues.slice(0, 5).map((issue) => <li key={`${issue.index}-${issue.message}`}>Record {issue.index + 1}: {issue.message}</li>)}</ul><p className="mt-2 text-[11px] text-[#848484]">Fix the export and select it again. Valid records will not be silently imported alongside malformed records.</p></div>}{validation.duplicates.length > 0 && <div className="rounded-xl border border-[#9a9a9a]/25 bg-[#9a9a9a]/[.06] p-4"><p className="text-sm font-medium text-[#c2c2c2]">{validation.duplicates.length} duplicate{validation.duplicates.length === 1 ? "" : "s"} skipped</p><p className="mt-1 text-xs leading-5 text-[#9b9b9b]">{validation.duplicates.map((duplicate) => `${duplicate.sessionId} (${duplicate.reason === "already-imported" ? "Already imported" : "Repeated in file"})`).join(" · ")}</p></div>}{validation.sessions.length > 0 && <div className="rounded-xl border border-white/[.07] bg-black/10 p-4"><div className="flex items-center justify-between"><p className="text-sm font-medium">Preview imported sessions</p><Pill tone="green"><Check className="size-3"/> Validated</Pill></div><div className="mt-3 space-y-2">{validation.sessions.slice(0, 6).map((session) => <div key={session.sessionId} className="flex items-center justify-between gap-3 rounded-lg bg-white/[.025] px-3 py-2 text-xs"><div className="min-w-0"><p className="truncate font-medium">{session.archetype.primary}</p><p className="mt-1 text-[10px] text-[#7a7a7a]">{dateLabel(session.startedAt)} · {session.sessionId}</p></div><span className="mono shrink-0 text-[#d0d0d0]">{formatDuration(session.activeDurationSeconds)}</span></div>)}</div>{validation.sessions.length > 6 && <p className="mt-2 text-[10px] text-[#797979]">+ {validation.sessions.length - 6} more validated sessions</p>}</div>}</>}</div><div className="flex flex-col-reverse gap-2 border-t border-white/[.07] p-5 sm:flex-row sm:justify-end sm:p-6"><button onClick={close} className="min-h-11 rounded-lg border border-white/[.09] px-4 text-sm text-[#bdbdbd]">Cancel</button><button onClick={confirm} disabled={!validation?.sessions.length || Boolean(validation.issues.length)} className="min-h-11 rounded-lg bg-[#f2f2f2] text-[#0b0b0b] px-4 text-sm font-semibold disabled:cursor-not-allowed disabled:opacity-40">Import validated sessions</button></div></div></div>;
}

export function OverviewPage() {
  const { sessions, preferences } = useSprintly();
  const [importOpen, setImportOpen] = useState(false);
  const records = recordsOf(sessions);
  const weekly = filterSessionsByRange(records, "week");
  const aggregate = aggregateSessions(weekly);
  const streaks = getStreakStats(records);
  const achievements = computeAchievements(records, streaks);
  const recordsBest = computePersonalRecords(records, streaks);
  const days = useMemo(() => {
    const now = new Date();
    return Array.from({ length: 7 }, (_, index) => {
      const day = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() - (6 - index)));
      const key = day.toISOString().slice(0, 10);
      const hours = weekly.filter((session) => session.startedAt.slice(0, 10) === key).reduce((sum, session) => sum + session.activeDurationSeconds, 0) / 3600;
      return { label: new Intl.DateTimeFormat("en", { weekday: "short" }).format(day), hours };
    });
  }, [weekly]);
  const archetype = aggregate.archetype;
  return <div><PageHeader eyebrow="Sprintly · your record" title={`Good to see you, ${DEMO_USER.displayName.split(" ")[0]}.`} description="A playful, private view of your actual imported sessions. The website never invents telemetry or reads extension storage." action={<button onClick={() => setImportOpen(true)} className="inline-flex min-h-11 items-center gap-2 rounded-lg bg-[#f2f2f2] text-[#0b0b0b] px-4 text-sm font-semibold"><FileUp className="size-4"/> Import data</button>}/><Panel className="relative mb-3 overflow-hidden p-5 sm:p-7"><div className="absolute right-0 top-0 h-full w-1/2 bg-[radial-gradient(circle_at_75%_15%,rgba(128,128,128,.2),transparent_55%)]"/><div className="relative grid gap-8 lg:grid-cols-[1.35fr_.65fr] lg:items-center"><div><div className="flex flex-wrap gap-2"><Pill tone="amber"><Flame className="size-3"/> {streaks.current}-day streak</Pill><Pill tone="violet"><Sparkles className="size-3"/> {archetype}</Pill><Pill tone={preferences.profileVisibility === "public" ? "green" : "gray"}><EyeOff className="size-3"/> {preferences.profileVisibility === "public" ? "Public profile" : "Private profile"}</Pill></div><h2 className="mt-6 max-w-2xl text-3xl font-semibold leading-tight tracking-[-.055em] sm:text-4xl">Your work has a shape. This week, it looks like momentum.</h2><p className="mt-3 max-w-xl text-sm leading-6 text-[#939393]">{aggregate.sessionCount} real session{aggregate.sessionCount === 1 ? "" : "s"} · {formatDuration(aggregate.activeDurationSeconds)} of deliberate coding · current Dev Score {aggregate.scores.devScore}.</p><Link href="/app/analytics" className="mt-6 inline-flex min-h-10 items-center gap-2 text-xs font-semibold text-[#d0d0d0]">Open weekly recap <ChevronRight className="size-3.5"/></Link></div><div className="flex items-center gap-5 lg:justify-end"><div className="grid size-28 place-items-center rounded-full" style={{ background: `conic-gradient(#f2f2f2 0 ${Math.min(100, aggregate.scores.focus)}%, #252525 ${Math.min(100, aggregate.scores.focus)}% 100%)` }}><div className="grid size-[92px] place-items-center rounded-full bg-[#141414] text-center"><div><p className="mono text-2xl font-semibold">{aggregate.scores.focus}</p><p className="text-[10px] text-[#7a7a7a]">focus</p></div></div></div><div><p className="mono text-xl font-semibold">{aggregate.coding.aiAssistedPercent}%</p><p className="mt-1 text-xs text-[#878787]">AI-assisted</p><p className="mt-4 text-xs text-[#e0e0e0]">{preferences.leaderboardOptIn ? "Leaderboard eligible" : "Not ranked yet"}</p></div></div></div></Panel><div className="grid grid-cols-2 gap-3 lg:grid-cols-6"><MetricCard icon={Timer} label="Coding time" value={formatDuration(aggregate.activeDurationSeconds)} note="This week"/><MetricCard icon={Activity} label="Focus" value={`${aggregate.scores.focus}`} note="Own-record score" tone="cyan"/><MetricCard icon={HeartPulse} label="Recovery" value={`${aggregate.reliability.recoveryRate}%`} note={`${aggregate.reliability.recoveredFailures}/${aggregate.reliability.failures || 0} recovered`} tone="green"/><MetricCard icon={Zap} label="Dev Score" value={`${computeCompositeDevScore(aggregate)}`} note="Version v1" tone="violet"/><MetricCard icon={Flame} label="Streak" value={`${streaks.current} days`} note={`Best ${streaks.longest}`} tone="amber"/><MetricCard icon={Code2} label="Sessions" value={number(aggregate.sessionCount)} note={`${number(aggregate.activity.edits)} edits`} tone="cyan"/></div><div className="mt-3 grid gap-3 xl:grid-cols-[1.25fr_.75fr]"><Panel className="p-5"><div className="flex items-center justify-between"><div><h2 className="text-sm font-semibold">Your week in motion</h2><p className="mt-1 text-xs text-[#7a7a7a]">Active coding by day · {dateRangeTitle("week")}</p></div><Pill tone="green">{aggregate.coding.manualPercent}% manual</Pill></div><div className="mt-8 flex h-48 items-end gap-2 sm:gap-4">{days.map((day) => <div key={day.label} className="flex h-full flex-1 flex-col items-center justify-end gap-2"><div className="w-full max-w-10 rounded-t-lg bg-gradient-to-t from-[#f2f2f2] to-[#bdbdbd]" style={{ height: `${Math.max(8, Math.min(100, day.hours * 18))}%` }} title={`${day.hours.toFixed(1)} hours`}/><span className="mono text-[10px] text-[#797979]">{day.label}</span></div>)}</div><div className="mt-5 grid grid-cols-3 gap-2 text-center"><div className="rounded-lg bg-white/[.025] p-3"><p className="mono text-sm font-semibold">{number(aggregate.activity.edits)}</p><p className="mt-1 text-[10px] text-[#7a7a7a]">edits</p></div><div className="rounded-lg bg-white/[.025] p-3"><p className="mono text-sm font-semibold">{number(aggregate.terminal.test)}</p><p className="mt-1 text-[10px] text-[#7a7a7a]">tests</p></div><div className="rounded-lg bg-white/[.025] p-3"><p className="mono text-sm font-semibold">{number(aggregate.ai.claudeCodePrompts + aggregate.ai.codexPrompts + aggregate.ai.copilotPrompts)}</p><p className="mt-1 text-[10px] text-[#7a7a7a]">AI prompts</p></div></div></Panel><Panel className="p-5"><div className="flex items-center justify-between"><h2 className="text-sm font-semibold">Coding mix</h2><Link href="/app/analytics" className="text-xs text-[#c2c2c2]">Details</Link></div><div className="mt-7 space-y-5"><div><div className="mb-2 flex justify-between text-xs"><span className="text-[#939393]">Manual</span><span className="mono">{aggregate.coding.manualPercent}%</span></div><Progress value={aggregate.coding.manualPercent} color="#f2f2f2"/></div><div><div className="mb-2 flex justify-between text-xs"><span className="text-[#939393]">AI-assisted</span><span className="mono">{aggregate.coding.aiAssistedPercent}%</span></div><Progress value={aggregate.coding.aiAssistedPercent} color="#bdbdbd"/></div><div><div className="mb-2 flex justify-between text-xs"><span className="text-[#939393]">Automation</span><span className="mono">{aggregate.coding.automationPercent}%</span></div><Progress value={aggregate.coding.automationPercent} color="#d0d0d0"/></div></div><div className="mt-8 rounded-xl border border-[#f2f2f2]/20 bg-[#f2f2f2]/[.06] p-4"><p className="text-sm font-medium">{archetype}</p><p className="mt-1 text-xs leading-5 text-[#8b8b8b]">{aggregate.traits.join(" · ") || "Your traits will emerge as sessions arrive."}</p></div></Panel></div><div className="mt-3 grid gap-3 lg:grid-cols-3"><Panel className="p-5"><div className="flex items-center justify-between"><h2 className="text-sm font-semibold">Personal records</h2><Link href="/app/profile" className="text-xs text-[#c2c2c2]">Profile</Link></div><div className="mt-5 space-y-4">{[[Trophy, "Longest session", formatDuration(recordsBest.longestSessionSeconds)],[Flame, "Longest streak", `${recordsBest.longestStreak} days`],[Rocket, "Best weekly score", `${recordsBest.bestWeeklyDevScore}`]].map(([Icon, label, value]) => { const RecordIcon = Icon as typeof Trophy; return <div key={String(label)} className="flex items-center gap-3"><div className="grid size-9 place-items-center rounded-lg bg-white/[.04]"><RecordIcon className="size-4 text-[#f2f2f2]"/></div><div><p className="text-xs text-[#838383]">{String(label)}</p><p className="mono mt-1 text-sm font-semibold">{String(value)}</p></div></div>; })}</div></Panel><Panel className="p-5"><div className="flex items-center justify-between"><h2 className="text-sm font-semibold">Recent sessions</h2><Link href="/app/sessions" className="text-xs text-[#c2c2c2]">History</Link></div><div className="mt-4 space-y-3">{records.slice().sort((a, b) => b.startedAt.localeCompare(a.startedAt)).slice(0, 3).map((session) => <Link key={session.sessionId} href={`/app/sessions/${session.sessionId}`} className="flex items-center gap-3 rounded-lg p-2 hover:bg-white/[.04]"><div className={`grid size-9 place-items-center rounded-lg bg-gradient-to-br ${avatarStyle(session.archetype.primary, session.archetype.traits)}`}><Code2 className="size-4"/></div><div className="min-w-0 flex-1"><p className="truncate text-xs font-medium">{session.archetype.primary}</p><p className="mt-1 text-[10px] text-[#7a7a7a]">{shortDate(session.startedAt)} · {formatDuration(session.activeDurationSeconds)}</p></div><span className="mono text-xs text-[#d0d0d0]">{session.scores.devScore}</span></Link>)}</div></Panel><Panel className="p-5"><div className="flex items-center justify-between"><h2 className="text-sm font-semibold">Achievements</h2><Link href="/app/achievements" className="text-xs text-[#c2c2c2]">See all</Link></div><div className="mt-5 space-y-3">{achievements.filter((achievement) => achievement.unlocked).slice(0, 3).map((achievement) => <div key={achievement.id} className="flex items-center gap-3"><div className="grid size-9 place-items-center rounded-full bg-[#9a9a9a]/10 text-[#9a9a9a]"><Medal className="size-4"/></div><div><p className="text-xs font-medium">{achievement.title}</p><p className="mt-1 text-[10px] text-[#7a7a7a]">Actual progress · unlocked</p></div></div>)}{!achievements.some((achievement) => achievement.unlocked) && <p className="text-xs text-[#7d7d7d]">Your first achievement will appear after the first validated session.</p>}</div></Panel></div><ImportFlow open={importOpen} onClose={() => setImportOpen(false)}/></div>;
}

export function SessionsPage() {
  const { sessions } = useSprintly();
  const [range, setRange] = useState<DateRange>("week");
  const [sort, setSort] = useState<"newest" | "longest" | "score">("newest");
  const [custom, setCustom] = useState({ from: "2026-08-01", to: "2026-08-31" });
  const [importOpen, setImportOpen] = useState(false);
  const records = recordsOf(sessions);
  const visible = filterSessionsByRange(records, range, new Date(), custom).sort((a, b) => sort === "longest" ? b.activeDurationSeconds - a.activeDurationSeconds : sort === "score" ? b.scores.devScore - a.scores.devScore : b.startedAt.localeCompare(a.startedAt));
  const aggregate = aggregateSessions(visible);
  return <div><PageHeader eyebrow="Cloud history · explicit imports" title="Session history" description="Every row is an imported or authorized session. Duplicate session IDs are skipped and invalid records never enter this list." action={<button onClick={() => setImportOpen(true)} className="inline-flex min-h-11 items-center gap-2 rounded-lg bg-[#f2f2f2] text-[#0b0b0b] px-4 text-sm font-semibold"><FileUp className="size-4"/> Import JSON</button>}/><div className="mb-4 flex flex-col gap-3 rounded-xl border border-white/[.07] bg-white/[.02] p-3 sm:flex-row sm:items-center"><div className="flex gap-2 overflow-x-auto">{(["today", "week", "month", "all", "custom"] as DateRange[]).map((item) => <button key={item} onClick={() => setRange(item)} className={`min-h-10 shrink-0 rounded-lg px-3 text-xs ${range === item ? "bg-[#f2f2f2] text-[#0b0b0b]" : "text-[#8b8b8b] hover:bg-white/[.04]"}`}>{dateRangeTitle(item)}</button>)}</div><div className="ml-auto flex items-center gap-2"><label htmlFor="session-sort" className="text-[10px] uppercase tracking-[.14em] text-[#6d6d6d]">Sort</label><select id="session-sort" value={sort} onChange={(event) => setSort(event.target.value as typeof sort)} className="h-9 rounded-lg border border-white/[.08] bg-[#181818] px-2 text-xs text-[#c8c8c8]"><option value="newest">Newest</option><option value="longest">Longest</option><option value="score">Dev Score</option></select></div></div>{range === "custom" && <div className="mb-4 flex flex-wrap items-center gap-3 rounded-xl border border-white/[.07] bg-white/[.02] p-3 text-xs"><label>From <input type="date" value={custom.from} onChange={(event) => setCustom({ ...custom, from: event.target.value })} className="ml-2 h-9 rounded-lg border border-white/[.08] bg-[#181818] px-2 text-xs"/></label><label>To <input type="date" value={custom.to} onChange={(event) => setCustom({ ...custom, to: event.target.value })} className="ml-2 h-9 rounded-lg border border-white/[.08] bg-[#181818] px-2 text-xs"/></label></div>}<div className="mb-4 grid grid-cols-2 gap-3 md:grid-cols-4"><MetricCard icon={Timer} label="Coding time" value={formatDuration(aggregate.activeDurationSeconds)} note={`${aggregate.sessionCount} sessions`}/><MetricCard icon={Activity} label="Edits" value={number(aggregate.activity.edits)} note={`${number(aggregate.activity.filesTouched)} files touched`} tone="cyan"/><MetricCard icon={Terminal} label="Builds + tests" value={number(aggregate.terminal.build + aggregate.terminal.test)} note={`${number(aggregate.terminal.test)} tests`} tone="green"/><MetricCard icon={Trophy} label="Average score" value={`${aggregate.scores.devScore}`} note={`${aggregate.scores.focus}% focus`} tone="amber"/></div><div className="space-y-3">{visible.map((session) => <SessionRow key={session.sessionId} session={session}/>)}{!visible.length && <Panel className="grid min-h-64 place-items-center p-6 text-center"><div><FileUp className="mx-auto size-8 text-[#f2f2f2]"/><p className="mt-4 text-sm font-medium">No sessions in this range</p><p className="mt-2 text-xs text-[#7d7d7d]">Import an extension export or choose another date range.</p></div></Panel>}</div><ImportFlow open={importOpen} onClose={() => setImportOpen(false)}/></div>;
}

function SessionRow({ session }: { session: SprintlySession }) {
  const [expanded, setExpanded] = useState(false);
  return <Panel className="overflow-hidden"><button onClick={() => setExpanded((value) => !value)} aria-expanded={expanded} className="grid min-h-[94px] w-full gap-4 p-4 text-left sm:grid-cols-[125px_1fr_auto] sm:items-center sm:p-5"><div><p className="text-xs font-medium">{dateLabel(session.startedAt)}</p><p className="mono mt-1 text-[10px] text-[#797979]">{new Intl.DateTimeFormat("en", { hour: "2-digit", minute: "2-digit" }).format(new Date(session.startedAt))}</p></div><div className="flex min-w-0 items-center gap-3"><div className={`grid size-10 shrink-0 place-items-center rounded-lg bg-gradient-to-br ${avatarStyle(session.archetype.primary, session.archetype.traits)}`}><Code2 className="size-4"/></div><div className="min-w-0"><p className="truncate text-sm font-medium">{session.archetype.primary}</p><p className="mt-1 truncate text-xs text-[#7e7e7e]">{session.archetype.traits.join(" · ")}</p></div></div><div className="flex items-center gap-5"><div className="text-right"><p className="mono text-base font-semibold">{formatDuration(session.activeDurationSeconds)}</p><p className="mt-1 text-[10px] text-[#c0c0c0]">{session.scores.focus}% focus</p></div><ChevronDown className={`size-4 text-[#6c6c6c] transition-transform ${expanded ? "rotate-180" : ""}`}/></div></button>{expanded && <div className="border-t border-white/[.07] bg-black/10 p-4 sm:p-5"><div className="grid grid-cols-2 gap-2 sm:grid-cols-5">{[[FileCode2, number(session.activity.filesTouched), "files"], [Code2, number(session.activity.edits), "edits"], [Terminal, number(session.terminal.totalCommands), "commands"], [HeartPulse, `${session.reliability.recoveryRate}%`, "recovery"], [Trophy, session.scores.devScore.toString(), "dev score"]].map(([Icon, value, label]) => { const C = Icon as typeof FileCode2; return <div key={String(label)} className="rounded-lg bg-white/[.025] p-3"><C className="size-3.5 text-[#767676]"/><p className="mono mt-3 text-sm font-semibold">{String(value)}</p><p className="mt-1 text-[10px] text-[#777777]">{String(label)}</p></div>; })}</div><div className="mt-4 flex flex-wrap items-center gap-3"><Link href={`/app/sessions/${session.sessionId}`} className="inline-flex min-h-10 items-center gap-2 rounded-lg bg-[#f2f2f2] text-[#0b0b0b] px-3 text-xs font-semibold">Open full session <ChevronRight className="size-3.5"/></Link><Pill tone="gray"><HardDrive className="size-3"/> {session.signature ? "Signed · not verified" : "Demo / unverified"}</Pill></div></div>}</Panel>;
}

export function SessionDetailPage() {
  const params = useParams<{ id?: string | string[] }>();
  const { sessions } = useSprintly();
  const rawId = params?.id;
  const id = Array.isArray(rawId) ? rawId[0] : rawId;
  const session = sessions.map((item) => item.record).find((record) => record.sessionId === id) ?? sessions[0]?.record;
  if (!session) return <Panel className="p-8"><p className="text-sm">No session found. Import a Sprintly export to begin.</p></Panel>;
  return <div><PageHeader eyebrow={`Session · ${session.sessionId}`} title={session.archetype.primary} description={`${dateLabel(session.startedAt)} · ${formatDuration(session.activeDurationSeconds)} · aggregate data only`} action={<Link href={`/app/share?kind=session&sessionId=${session.sessionId}`} className="inline-flex min-h-11 items-center gap-2 rounded-lg bg-[#f2f2f2] text-[#0b0b0b] px-4 text-sm font-semibold"><Upload className="size-4"/> Create share card</Link>}/><Panel className="relative overflow-hidden p-6 sm:p-8"><div className="absolute right-0 top-0 h-full w-1/2 bg-[radial-gradient(circle_at_70%_20%,rgba(157,157,157,.14),transparent_55%)]"/><div className="relative grid gap-8 lg:grid-cols-[1fr_auto] lg:items-center"><div><div className="flex flex-wrap gap-2"><Pill tone="cyan"><Clock3 className="size-3"/> {formatDuration(session.activeDurationSeconds)}</Pill><Pill tone="green"><ShieldCheck className="size-3"/> {session.signature && session.publicKeyId ? "Signed · not verified" : "Unverified packet"}</Pill></div><p className="mono mt-8 text-6xl font-semibold tracking-[-.07em]">{formatDuration(session.activeDurationSeconds)}</p><p className="mt-3 text-sm text-[#8b8b8b]">{session.scores.focus}% focused · Dev Score {session.scores.devScore}</p><div className="mt-5 flex flex-wrap gap-2">{session.archetype.traits.map((trait) => <Pill key={trait} tone="gray">{trait}</Pill>)}</div></div><div className="grid grid-cols-2 gap-2">{[[FileCode2, number(session.activity.filesTouched), "files"], [Code2, number(session.activity.edits), "edits"], [Terminal, number(session.terminal.totalCommands), "terminal"], [HeartPulse, `${session.reliability.recoveryRate}%`, "recovery"]].map(([Icon, value, label]) => { const C = Icon as typeof FileCode2; return <div key={String(label)} className="min-w-[110px] rounded-xl border border-white/[.07] bg-white/[.025] p-4"><C className="size-4 text-[#d6d6d6]"/><p className="mono mt-3 text-xl font-semibold">{String(value)}</p><p className="mt-1 text-xs text-[#808080]">{String(label)}</p></div>; })}</div></div></Panel><div className="mt-3 grid gap-3 xl:grid-cols-2"><Panel className="p-5"><h2 className="text-sm font-semibold">Coding mix</h2><div className="mt-6 space-y-5"><MixRow label="Manual" value={session.coding.manualPercent} color="#f2f2f2"/><MixRow label="AI-assisted" value={session.coding.aiAssistedPercent} color="#bdbdbd"/><MixRow label="Automation" value={session.coding.automationPercent} color="#d0d0d0"/></div></Panel><Panel className="p-5"><h2 className="text-sm font-semibold">Quality signals</h2><div className="mt-6 grid grid-cols-2 gap-3">{[["Focus", session.scores.focus], ["Testing discipline", session.scores.testingDiscipline], ["Recovery", session.scores.recovery], ["AI balance", session.scores.aiBalance]].map(([label, value]) => <div key={String(label)} className="rounded-xl border border-white/[.07] bg-white/[.025] p-4"><p className="text-xs text-[#838383]">{String(label)}</p><p className="mono mt-3 text-2xl font-semibold">{String(value)}</p><div className="mt-3"><Progress value={Number(value)} color="#d2d2d2"/></div></div>)}</div></Panel><Panel className="p-5"><h2 className="text-sm font-semibold">Terminal activity</h2><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4">{[["Builds", session.terminal.build], ["Tests", session.terminal.test], ["Git", session.terminal.git], ["Other", session.terminal.other]].map(([label, value]) => <div key={String(label)} className="rounded-xl bg-white/[.025] p-4"><Terminal className="size-4 text-[#bdbdbd]"/><p className="mono mt-3 text-xl font-semibold">{String(value)}</p><p className="mt-1 text-xs text-[#7d7d7d]">{String(label)}</p></div>)}</div></Panel><Panel className="p-5"><h2 className="text-sm font-semibold">AI activity</h2><div className="mt-5 space-y-3">{[["Claude Code", session.ai.claudeCodePrompts], ["Codex", session.ai.codexPrompts], ["Copilot", session.ai.copilotPrompts]].map(([label, value]) => <div key={String(label)} className="flex items-center justify-between rounded-lg bg-white/[.025] px-3 py-3 text-xs"><span>{String(label)}</span><span className="mono text-[#d0d0d0]">{String(value)} prompts</span></div>)}<p className="pt-2 text-[11px] leading-5 text-[#7d7d7d]">Prompts, source code, raw terminal output, and secrets are not published by this view.</p></div></Panel></div></div>;
}

function MixRow({ label, value, color }: { label: string; value: number; color: string }) { return <div><div className="mb-2 flex justify-between text-xs"><span className="text-[#939393]">{label}</span><span className="mono">{value}%</span></div><Progress value={value} color={color}/></div>; }

export function AnalyticsPage() {
  const { sessions } = useSprintly();
  const records = recordsOf(sessions);
  const [range, setRange] = useState<"week" | "month">("week");
  const filtered = filterSessionsByRange(records, range);
  const aggregate = aggregateSessions(filtered);
  const streaks = getStreakStats(records);
  const previous = range === "week" ? filterSessionsByRange(records, "custom", new Date(), { from: "2026-08-01", to: "2026-08-07" }) : filterSessionsByRange(records, "custom", new Date(), { from: "2026-07-01", to: "2026-07-31" });
  const previousAggregate = aggregateSessions(previous);
  const change = previousAggregate.activeDurationSeconds ? Math.round(((aggregate.activeDurationSeconds - previousAggregate.activeDurationSeconds) / previousAggregate.activeDurationSeconds) * 100) : 0;
  return <div>
    <PageHeader eyebrow="Recap · own activity only" title={`${range === "week" ? "This week" : "This month"}, decoded.`} description="Compare your current activity with your previous personal window. No global benchmark is used to manipulate the numbers." action={<div className="flex gap-2">{(["week", "month"] as const).map((item) => <button key={item} onClick={() => setRange(item)} className={`min-h-10 rounded-lg px-3 text-xs ${range === item ? "bg-[#f2f2f2] text-[#0b0b0b]" : "border border-white/[.08] text-[#8b8b8b]"}`}>{item === "week" ? "This week" : "This month"}</button>)}</div>} />
    <div className="grid grid-cols-2 gap-3 lg:grid-cols-5">
      <MetricCard icon={Timer} label="Coding time" value={formatDuration(aggregate.activeDurationSeconds)} note={`${change >= 0 ? "+" : ""}${change}% vs previous`} />
      <MetricCard icon={Code2} label="Sessions" value={number(aggregate.sessionCount)} note={`${number(aggregate.activity.edits)} edits`} tone="cyan" />
      <MetricCard icon={Activity} label="Focus" value={`${aggregate.scores.focus}`} note={`Previous ${previousAggregate.scores.focus}`} tone="green" />
      <MetricCard icon={HeartPulse} label="Recovery" value={`${aggregate.reliability.recoveryRate}%`} note={`${aggregate.reliability.failures} failures`} tone="amber" />
      <MetricCard icon={Flame} label="Streak" value={`${streaks.current} days`} note={`Best ${streaks.longest}`} tone="amber" />
    </div>
    <div className="mt-3 grid gap-3 xl:grid-cols-[1.2fr_.8fr]">
      <Panel className="p-5"><div className="flex items-center justify-between"><div><h2 className="text-sm font-semibold">Coding mix</h2><p className="mt-1 text-xs text-[#7a7a7a]">Weighted across {aggregate.sessionCount} validated sessions</p></div><Pill tone="violet">Dev Score {computeCompositeDevScore(aggregate)}</Pill></div><div className="mt-8 space-y-6"><MixRow label="Manual" value={aggregate.coding.manualPercent} color="#f2f2f2"/><MixRow label="AI-assisted" value={aggregate.coding.aiAssistedPercent} color="#bdbdbd"/><MixRow label="Automation" value={aggregate.coding.automationPercent} color="#d0d0d0"/></div><div className="mt-8 grid grid-cols-2 gap-3 sm:grid-cols-4">{[["Builds", aggregate.terminal.build], ["Tests", aggregate.terminal.test], ["Files", aggregate.activity.filesTouched], ["Prompts", aggregate.ai.claudeCodePrompts + aggregate.ai.codexPrompts + aggregate.ai.copilotPrompts]].map(([label, value]) => <div key={String(label)} className="rounded-lg bg-white/[.025] p-3"><p className="mono text-lg font-semibold">{number(Number(value))}</p><p className="mt-1 text-[10px] text-[#7a7a7a]">{String(label)}</p></div>)}</div></Panel>
      <Panel className="p-5"><div className="flex items-center justify-between"><h2 className="text-sm font-semibold">Quality pulse</h2><Radar className="size-4 text-[#d2d2d2]" /></div><div className="mt-6 space-y-5"><MixRow label="Focus" value={aggregate.scores.focus} color="#d2d2d2"/><MixRow label="Testing discipline" value={aggregate.scores.testingDiscipline} color="#bdbdbd"/><MixRow label="Consistency" value={aggregate.scores.consistency} color="#d0d0d0"/><MixRow label="AI balance" value={aggregate.scores.aiBalance} color="#9a9a9a"/></div><div className="mt-8 rounded-xl border border-[#d0d0d0]/15 bg-[#d0d0d0]/[.04] p-4"><p className="text-sm font-medium">{aggregate.archetype}</p><p className="mt-1 text-xs leading-5 text-[#858585]">{aggregate.traits.join(" · ") || "Traits appear as your record grows."}</p></div></Panel>
    </div>
    <div className="mt-3 grid gap-3 md:grid-cols-2"><Panel className="p-5"><div className="flex items-center justify-between"><div><h2 className="text-sm font-semibold">Weekly recap</h2><p className="mt-1 text-xs text-[#7a7a7a]">A card you can customize before sharing</p></div><Link href="/app/share?kind=weekly" className="inline-flex min-h-9 items-center gap-2 rounded-lg bg-[#f2f2f2] text-[#0b0b0b] px-3 text-xs font-semibold">Create card <Upload className="size-3.5" /></Link></div><p className="mt-6 text-2xl font-semibold tracking-[-.04em]">{aggregate.sessionCount} sessions · {formatDuration(aggregate.activeDurationSeconds)}</p><p className="mt-2 text-xs text-[#8b8b8b]">{aggregate.coding.aiAssistedPercent}% AI-assisted · {aggregate.reliability.recoveryRate}% recovery · {streaks.current} day streak.</p></Panel><Panel className="p-5"><h2 className="text-sm font-semibold">Privacy boundary</h2><p className="mt-3 text-xs leading-5 text-[#858585]">These aggregates are computed from selected sessions. Raw prompts, code, terminal output, and secrets never enter the social layer.</p><Link href="/app/settings" className="mt-5 inline-flex min-h-10 items-center gap-2 text-xs font-semibold text-[#c2c2c2]">Review privacy controls <ChevronRight className="size-3.5" /></Link></Panel></div>
  </div>;
}

export function AchievementsPage() {
  const { sessions } = useSprintly();
  const records = recordsOf(sessions);
  const streaks = getStreakStats(records);
  const achievements = computeAchievements(records, streaks);
  const unlocked = achievements.filter((achievement) => achievement.unlocked).length;
  return <div><PageHeader eyebrow="Progress · earned from real sessions" title="Achievements with receipts." description="Every badge below is calculated from validated activity. There is no fake progress bar and no automatic credit for unimported work." action={<Pill tone="amber"><Medal className="size-3"/> {unlocked}/{achievements.length} unlocked</Pill>}/><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{achievements.map((achievement) => <AchievementCard key={achievement.id} achievement={achievement}/>)}</div></div>;
}

function AchievementCard({ achievement }: { achievement: Achievement }) {
  const Icon = achievement.unlocked ? CheckCircle2 : achievement.icon === "flame" ? Flame : achievement.icon === "moon" ? Moon : achievement.icon === "terminal" ? Terminal : achievement.icon === "heart" ? HeartPulse : Medal;
  return <Panel className={`p-5 ${achievement.unlocked ? "border-[#9a9a9a]/20" : "opacity-75"}`}><div className="flex items-start justify-between"><div className={`grid size-11 place-items-center rounded-full ${achievement.unlocked ? "bg-[#9a9a9a]/10 text-[#9a9a9a]" : "bg-white/[.04] text-[#6c6c6c]"}`}><Icon className="size-5"/></div>{achievement.unlocked && <Pill tone="amber">Unlocked</Pill>}</div><h2 className="mt-6 text-sm font-semibold">{achievement.title}</h2><p className="mt-2 min-h-10 text-xs leading-5 text-[#838383]">{achievement.description}</p><div className="mt-5"><div className="mb-2 flex justify-between text-[10px] text-[#7a7a7a]"><span>{achievement.progress}% complete</span><span>{achievement.unlocked ? "Done" : `${achievement.target} target`}</span></div><Progress value={achievement.progress} color={achievement.unlocked ? "#9a9a9a" : "#5c5c5c"}/></div></Panel>;
}

export function ProfilePage() {
  const { sessions, profile, preferences, updatePreferences } = useSprintly();
  const records = recordsOf(sessions);
  const aggregate = aggregateSessions(records);
  const streaks = getStreakStats(records);
  const achievements = computeAchievements(records, streaks);
  const personal = computePersonalRecords(records, streaks);
  const avatar = avatarStyle(aggregate.archetype, aggregate.traits);
  return <div><PageHeader eyebrow="Developer identity" title={profile.displayName} description={preferences.profileVisibility === "public" ? "Your selected summary is public. Raw sessions and unselected statistics remain private." : "Your profile is private. Turn on public visibility only when you are ready to share the selected summary."} action={<Link href="/app/share?kind=profile" className="inline-flex min-h-11 items-center gap-2 rounded-lg border border-white/[.08] px-4 text-sm text-[#cacaca]"><Upload className="size-4"/> Customize profile card</Link>}/><Panel className="relative overflow-hidden p-6 sm:p-8"><div className="absolute right-0 top-0 h-full w-1/2 bg-[radial-gradient(circle_at_70%_20%,rgba(128,128,128,.18),transparent_55%)]"/><div className="relative flex flex-col gap-7 sm:flex-row sm:items-center"><div className={`grid size-24 shrink-0 place-items-center rounded-[28px] bg-gradient-to-br ${avatar} text-2xl font-semibold shadow-[0_16px_45px_rgba(128,128,128,.2)]`}>{initials(profile.displayName)}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h2 className="text-2xl font-semibold tracking-[-.04em]">@{profile.handle}</h2><Pill tone={preferences.profileVisibility === "public" ? "green" : "gray"}>{preferences.profileVisibility === "public" ? <><Globe2 className="size-3"/> Public</> : <><LockKeyhole className="size-3"/> Private</>}</Pill></div><p className="mt-2 text-sm text-[#929292]">{profile.city} · {profile.region} · {profile.bio}</p><div className="mt-5 flex flex-wrap gap-6">{[[`${streaks.current} days`, "streak"], [formatDuration(aggregate.activeDurationSeconds), "coding time"], [number(records.length), "sessions"], [number(achievements.filter((item) => item.unlocked).length), "achievements"]].map(([value, label]) => <div key={String(label)}><p className="mono text-lg font-semibold">{String(value)}</p><p className="mt-1 text-[10px] text-[#7a7a7a]">{String(label)}</p></div>)}</div></div><div className="rounded-xl border border-[#f2f2f2]/25 bg-[#f2f2f2]/[.08] p-4 sm:min-w-[230px]"><div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-lg bg-[#f2f2f2]/15"><Sparkles className="size-5 text-[#c2c2c2]"/></div><div><p className="text-sm font-semibold">{aggregate.archetype}</p><p className="text-[10px] text-[#8e8e8e]">Derived deterministically from your record</p></div></div><div className="mt-4"><Progress value={Math.min(100, aggregate.scores.devScore / 10)} /></div><p className="mt-3 text-[10px] text-[#7d7d7d]">Dev Score {buildLeaderboardPacket(records, profile.country).devScore} · version v1</p></div></div></Panel><div className="mt-3 grid gap-3 xl:grid-cols-[1.35fr_.65fr]"><Panel className="p-5"><div className="flex items-center justify-between"><div><h2 className="text-sm font-semibold">Achievements</h2><p className="mt-1 text-xs text-[#7a7a7a]">Unlocked from actual sessions</p></div><Link href="/app/achievements" className="text-xs text-[#c2c2c2]">View all</Link></div><div className="mt-5 grid grid-cols-2 gap-2 sm:grid-cols-3">{achievements.slice(0, 6).map((achievement) => <div key={achievement.id} className={`rounded-xl border p-4 ${achievement.unlocked ? "border-[#9a9a9a]/20 bg-[#9a9a9a]/[.04]" : "border-white/[.07] bg-white/[.02] opacity-55"}`}><div className="grid size-9 place-items-center rounded-full bg-white/[.05] text-[#9a9a9a]"><Medal className="size-4"/></div><p className="mt-4 text-xs font-medium">{achievement.title}</p><p className="mt-1 text-[10px] text-[#787878]">{achievement.unlocked ? "Unlocked" : `${achievement.progress}% complete`}</p></div>)}</div></Panel><Panel className="p-5"><h2 className="text-sm font-semibold">Personal records</h2><div className="mt-5 space-y-5">{[[Trophy, "Longest session", formatDuration(personal.longestSessionSeconds)], [Flame, "Longest streak", `${personal.longestStreak} days`], [HeartPulse, "Best recovery", `${personal.bestRecovery}%`], [Rocket, "Best weekly score", `${personal.bestWeeklyDevScore}`]].map(([Icon, label, value]) => { const C = Icon as typeof Trophy; return <div key={String(label)} className="flex items-center gap-3"><div className="grid size-9 place-items-center rounded-lg bg-white/[.04]"><C className="size-4 text-[#f2f2f2]"/></div><div><p className="text-xs text-[#838383]">{String(label)}</p><p className="mono mt-1 text-sm font-semibold">{String(value)}</p></div></div>; })}</div></Panel></div><Panel className="mt-3 p-5"><div className="flex flex-col gap-4 sm:flex-row sm:items-center"><div className="grid size-11 place-items-center rounded-xl bg-[#f2f2f2]/10 text-[#d2d2d2]"><Eye className="size-5"/></div><div className="flex-1"><h2 className="text-sm font-semibold">Profile visibility</h2><p className="mt-1 text-xs leading-5 text-[#858585]">Public profiles show your name, archetype, coding mix, selected scores, streak, and achievements. They never expose raw history.</p></div><div className="flex items-center gap-2"><button onClick={() => updatePreferences({ profileVisibility: "private" })} className={`min-h-10 rounded-lg px-3 text-xs ${preferences.profileVisibility === "private" ? "border border-white/[.1] text-white" : "text-[#7d7d7d]"}`}>Private</button><button onClick={() => updatePreferences({ profileVisibility: "public" })} className={`min-h-10 rounded-lg px-3 text-xs ${preferences.profileVisibility === "public" ? "bg-[#d0d0d0] text-[#0b0b0b] text-[#0e0e0e]" : "border border-white/[.1] text-[#bdbdbd]"}`}>Public</button></div></div><p className="mt-4 text-[11px] text-[#757575]">Change this setting here or in Privacy Center. Only explicitly selected summary fields are exposed.</p></Panel></div>;
}

