export function CommunityPage() {
  const { sessions, preferences, updatePreferences } = useSprintly();
  const records = recordsOf(sessions);
  const [scope, setScope] = useState<"global" | "country" | "region" | "city" | "friends">(preferences.leaderboardScope);
  const [joinOpen, setJoinOpen] = useState(false);
  const packet = buildLeaderboardPacket(records, scope === "global" ? "GLOBAL" : DEMO_USER.country);
  const current: LeaderboardEntry = { id: "demo-user", name: DEMO_USER.displayName, handle: `@${DEMO_USER.handle}`, avatar: initials(DEMO_USER.displayName), country: DEMO_USER.country, city: DEMO_USER.city, friends: [], ...packet, region: DEMO_USER.region };
  const all = [...demoLeaders, current].filter((entry) => scope === "global" || scope === "friends" ? scope === "global" || entry.friends.includes("demo-user") || entry.id === "demo-user" : scope === "country" ? entry.country === DEMO_USER.country : scope === "region" ? entry.region === DEMO_USER.region : entry.city === DEMO_USER.city).sort((a, b) => b.devScore - a.devScore);
  const join = () => { updatePreferences({ leaderboardOptIn: true, leaderboardScope: scope }); setJoinOpen(false); toast.success("Leaderboard participation enabled", { description: "Only the aggregate fields shown below are shared." }); };
  return <div><PageHeader eyebrow="Competition · consent first" title="Leaderboard, your way." description="Rankings use a versioned composite score—not raw coding hours. Global, country, region, city, and friends views are all optional." action={preferences.leaderboardOptIn ? <Pill tone="green"><ShieldCheck className="size-3"/> Opted in · {preferences.leaderboardScope}</Pill> : <button onClick={() => setJoinOpen(true)} className="inline-flex min-h-11 items-center gap-2 rounded-lg bg-[#f2f2f2] text-[#0b0b0b] px-4 text-sm font-semibold"><Trophy className="size-4"/> Join a leaderboard</button>}/>{!preferences.leaderboardOptIn && <Panel className="mb-3 border-[#9a9a9a]/20 bg-[#9a9a9a]/[.04] p-5"><div className="flex flex-col gap-4 sm:flex-row sm:items-center"><div className="grid size-11 place-items-center rounded-xl bg-[#9a9a9a]/10 text-[#9a9a9a]"><LockKeyhole className="size-5"/></div><div className="flex-1"><p className="text-sm font-medium">You are not ranked yet</p><p className="mt-1 text-xs leading-5 text-[#929292]">Joining is explicit. Your code, prompts, file names, raw terminal output, and complete history stay private.</p></div><button onClick={() => setJoinOpen(true)} className="min-h-10 rounded-lg border border-[#9a9a9a]/25 px-3 text-xs font-semibold text-[#c2c2c2]">Review shared fields</button></div></Panel>}<div className="mb-3 flex gap-2 overflow-x-auto">{(["global", "country", "region", "city", "friends"] as const).map((item) => <button key={item} onClick={() => setScope(item)} className={`min-h-10 shrink-0 rounded-lg px-4 text-xs capitalize ${scope === item ? "bg-white/[.08] text-white" : "text-[#828282] hover:bg-white/[.04]"}`}>{item}</button>)}</div><div className="grid gap-3 xl:grid-cols-[1.35fr_.65fr]"><Panel className="overflow-hidden"><div className="flex items-center justify-between border-b border-white/[.07] p-4"><div><h2 className="text-sm font-semibold">{scope === "global" ? "Global" : scope} rankings</h2><p className="mt-1 text-[10px] text-[#7a7a7a]">Week {packet.week} · Dev Score {packet.devScoreVersion}</p></div><Pill tone="violet">Composite score v1</Pill></div><div className="grid grid-cols-[45px_1fr_80px_60px] gap-3 border-b border-white/[.06] px-4 py-3 text-[10px] uppercase tracking-[.12em] text-[#686868] sm:grid-cols-[60px_1fr_100px_80px_80px]"><span>Rank</span><span>Developer</span><span>Dev Score</span><span>Streak</span><span>Focus</span></div>{all.map((entry, index) => <div key={entry.id} className={`grid min-h-[70px] grid-cols-[45px_1fr_80px_60px] items-center gap-3 border-b border-white/[.06] px-4 py-3 last:border-0 sm:grid-cols-[60px_1fr_100px_80px_80px] ${entry.id === "demo-user" ? "bg-[#f2f2f2]/[.08]" : ""}`}><div className={`mono text-sm font-semibold ${index < 3 ? "text-[#9a9a9a]" : "text-[#8b8b8b]"}`}>#{index + 1}</div><div className="flex min-w-0 items-center gap-3"><div className="grid size-9 shrink-0 place-items-center rounded-lg bg-gradient-to-br from-[#2c2c2c] to-[#1b1b1b] text-[10px] font-semibold">{entry.avatar}</div><div className="min-w-0"><p className="truncate text-sm font-medium">{entry.name}{entry.id === "demo-user" ? " · you" : ""}</p><p className="truncate text-[10px] text-[#767676]">{entry.handle}</p></div></div><span className="mono text-xs">{entry.devScore}</span><span className="flex items-center gap-1 text-xs text-[#aaaaaa]"><Flame className="size-3"/>{entry.streak}</span><span className="mono text-xs text-[#8b8b8b]">{entry.focusScore}</span></div>)}{!all.length && <div className="p-8 text-center text-xs text-[#7d7d7d]">No eligible friends in this view yet.</div>}</Panel><div className="space-y-3"><Panel className="p-5"><p className="mono text-[10px] uppercase tracking-[.15em] text-[#7d7d7d]">Your packet</p><div className="mt-5 grid grid-cols-2 gap-3">{[["Sessions", packet.sessions], ["Minutes", packet.activeMinutes], ["Focus", packet.focusScore], ["Recovery", packet.recoveryScore], ["Streak", packet.streak], ["Score", packet.devScore]].map(([label, value]) => <div key={String(label)} className="rounded-lg bg-white/[.025] p-3"><p className="mono text-lg font-semibold">{String(value)}</p><p className="mt-1 text-[10px] text-[#7a7a7a]">{String(label)}</p></div>)}</div><p className="mt-4 text-[11px] leading-5 text-[#7d7d7d]">Only this aggregate packet is eligible for sharing. `devScoreVersion: v1` travels with it.</p></Panel><Panel className="p-5"><h2 className="text-sm font-semibold">Leave leaderboard</h2><p className="mt-2 text-xs leading-5 text-[#858585]">Leaving stops future submissions. Existing demo rankings remain visible in this local prototype but are marked as no longer participating.</p>{preferences.leaderboardOptIn && <button onClick={() => { updatePreferences({ leaderboardOptIn: false }); toast.success("Leaderboard participation disabled"); }} className="mt-5 min-h-10 rounded-lg border border-[#b7b7b7]/25 px-3 text-xs font-semibold text-[#bababa]">Leave leaderboard</button>}</Panel></div></div>{joinOpen && <div className="fixed inset-0 z-[110] grid place-items-center bg-black/75 p-4 backdrop-blur-sm"><div role="dialog" aria-modal="true" className="w-full max-w-lg rounded-2xl border border-white/10 bg-[#141414] p-5 shadow-2xl sm:p-6"><div className="flex items-start justify-between"><div><p className="mono text-[10px] uppercase tracking-[.18em] text-[#9a9a9a]">Explicit consent</p><h2 className="mt-2 text-xl font-semibold">Join the {scope} leaderboard?</h2></div><button onClick={() => setJoinOpen(false)} aria-label="Close consent dialog" className="grid size-10 place-items-center rounded-lg text-[#7a7a7a]"><X className="size-4"/></button></div><p className="mt-4 text-sm leading-6 text-[#a8a8a8]">Sprintly will share an aggregate weekly packet only:</p><ul className="mt-4 space-y-2 text-xs text-[#cacaca]"><li>• Weekly Dev Score and version</li><li>• Session count and active minutes</li><li>• Focus, recovery, and streak</li></ul><p className="mt-4 text-xs leading-5 text-[#7d7d7d]">Your code, raw telemetry, prompts, file names, and terminal output are never published.</p><div className="mt-6 flex justify-end gap-2"><button onClick={() => setJoinOpen(false)} className="min-h-11 rounded-lg border border-white/[.09] px-4 text-sm text-[#bdbdbd]">Cancel</button><button onClick={join} className="min-h-11 rounded-lg bg-[#f2f2f2] text-[#0b0b0b] px-4 text-sm font-semibold">Join leaderboard</button></div></div></div>}</div>;
}

const defaultShareFields: ShareField[] = ["codingTime", "archetype", "codingMix", "recovery", "failures"];

function shareText(value: string) {
  return value.replace(/[&<>"']/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&apos;" })[character] ?? character);
}

function ShareCard({ title, payload, fields }: { title: string; payload: Partial<ReturnType<typeof buildSharePayload>>; fields: ShareField[] }) {
  const has = (field: ShareField) => fields.includes(field);
  return <div className="relative overflow-hidden rounded-[24px] border border-[#737373]/40 bg-[radial-gradient(circle_at_85%_8%,rgba(157,157,157,.22),transparent_36%),linear-gradient(145deg,#181818,#101217_65%)] p-6 shadow-[0_24px_80px_rgba(0,0,0,.35)] sm:p-8"><div className="absolute -right-12 -top-12 size-44 rounded-full bg-[#f2f2f2]/10 blur-2xl"/><div className="relative"><div className="flex items-center justify-between"><p className="mono text-[10px] font-semibold tracking-[.2em] text-[#d0d0d0]">SPRINTLY</p><span className="mono text-[10px] text-[#6e6e6e]">#Sprintly</span></div><p className="mono mt-10 text-[10px] uppercase tracking-[.18em] text-[#c7c7c7]">{title}</p>{has("archetype") && <h2 className="mt-3 text-3xl font-semibold tracking-[-.06em] sm:text-4xl">{payload.archetype || "New Builder"}</h2>}{has("codingTime") && <p className="mono mt-7 text-5xl font-semibold tracking-[-.08em] sm:text-6xl">{payload.codingTime || "0m"}</p>}{has("codingMix") && payload.codingMix && <div className="mt-7 grid grid-cols-3 gap-2"><div><p className="mono text-xl font-semibold">{payload.codingMix.manual}%</p><p className="mt-1 text-[10px] text-[#7d7d7d]">Manual</p></div><div><p className="mono text-xl font-semibold text-[#c7c7c7]">{payload.codingMix.aiAssisted}%</p><p className="mt-1 text-[10px] text-[#7d7d7d]">AI-assisted</p></div><div><p className="mono text-xl font-semibold text-[#e0e0e0]">{payload.codingMix.automation}%</p><p className="mt-1 text-[10px] text-[#7d7d7d]">Automation</p></div></div>}<div className="mt-8 grid grid-cols-2 gap-2">{has("recovery") && <div className="rounded-xl border border-white/[.08] bg-white/[.04] p-3"><p className="mono text-xl font-semibold">{payload.recovery ?? 0}%</p><p className="mt-1 text-[10px] text-[#7d7d7d]">Recovery</p></div>}{has("failures") && <div className="rounded-xl border border-white/[.08] bg-white/[.04] p-3"><p className="mono text-xl font-semibold">{payload.failures ?? 0}</p><p className="mt-1 text-[10px] text-[#7d7d7d]">Failures</p></div>}{has("tokenUsage") && <div className="rounded-xl border border-white/[.08] bg-white/[.04] p-3"><p className="mono text-xl font-semibold">{number(payload.tokenUsage ?? 0)}</p><p className="mt-1 text-[10px] text-[#7d7d7d]">Tokens</p></div>}{has("terminalActivity") && <div className="rounded-xl border border-white/[.08] bg-white/[.04] p-3"><p className="mono text-xl font-semibold">{payload.terminalActivity ?? 0}</p><p className="mt-1 text-[10px] text-[#7d7d7d]">Terminal events</p></div>}</div>{payload.streak !== undefined && <p className="mt-7 text-xs text-[#a1a1a1]">{payload.streak}-day streak · Dev Score {payload.devScore ?? 0}</p>}</div></div>;
}

function buildSvgCard(title: string, payload: Partial<ReturnType<typeof buildSharePayload>>, fields: ShareField[]) {
  const has = (field: ShareField) => fields.includes(field);
  const lines: string[] = ["SPRINTLY", title];
  if (has("archetype")) lines.push(payload.archetype || "New Builder");
  if (has("codingTime")) lines.push(payload.codingTime || "0m");
  if (has("codingMix") && payload.codingMix) lines.push(`Manual ${payload.codingMix.manual}% · AI ${payload.codingMix.aiAssisted}% · Auto ${payload.codingMix.automation}%`);
  if (has("recovery")) lines.push(`Recovery ${payload.recovery ?? 0}%`);
  if (has("failures")) lines.push(`Failures ${payload.failures ?? 0}`);
  if (has("tokenUsage")) lines.push(`Tokens ${number(payload.tokenUsage ?? 0)}`);
  if (has("terminalActivity")) lines.push(`Terminal events ${payload.terminalActivity ?? 0}`);
  return `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630"><defs><linearGradient id="bg" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#181818"/><stop offset="1" stop-color="#121212"/></linearGradient><radialGradient id="glow"><stop stop-color="#bdbdbd" stop-opacity=".35"/><stop offset="1" stop-color="#bdbdbd" stop-opacity="0"/></radialGradient></defs><rect width="1200" height="630" rx="32" fill="url(#bg)"/><circle cx="1040" cy="30" r="260" fill="url(#glow)"/><g fill="#f2f2f2" font-family="Arial, sans-serif">${lines.map((line, index) => `<text x="80" y="${90 + index * (index === 0 ? 0 : 64)}" font-size="${index === 0 ? 22 : index === 2 ? 54 : 28}" font-weight="${index <= 2 ? 700 : 500}" fill="${index === 1 ? "#c7c7c7" : "#f2f2f2"}">${shareText(line)}</text>`).join("")}<text x="80" y="570" font-size="18" fill="#7d7d7d">#Sprintly · explicit stats only</text></g></svg>`;
}

export function SharePage() {
  const search = useSearchParams();
  const { sessions, profile, createShare } = useSprintly();
  const records = recordsOf(sessions);
  const kind = (search.get("kind") as "session" | "weekly" | "achievement" | "profile" | null) || "weekly";
  const sessionId = search.get("sessionId");
  const session = records.find((record) => record.sessionId === sessionId);
  const aggregate = aggregateSessions(kind === "session" && session ? [session] : filterSessionsByRange(records, "week"));
  const streaks = getStreakStats(records);
  const payload = buildSharePayload(session, aggregate, streaks.current);
  const [fields, setFields] = useState<ShareField[]>(defaultShareFields);
  const [created, setCreated] = useState("");
  const title = kind === "session" ? "SESSION SNAPSHOT" : kind === "achievement" ? "ACHIEVEMENT UNLOCKED" : kind === "profile" ? "DEVELOPER PROFILE" : "WEEKLY RECAP";
  const toggle = (field: ShareField) => setFields((current) => current.includes(field) ? current.filter((item) => item !== field) : [...current, field]);
  const generate = () => {
    const id = `share_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
    const snapshot: ShareSnapshot = { id, ownerId: "demo-user", createdAt: new Date().toISOString(), kind: kind === "profile" || kind === "achievement" || kind === "session" ? kind : "weekly", title, selectedFields: fields, payload: Object.fromEntries(fields.map((field) => [field, payload[field]])) };
    createShare(snapshot);
    setCreated(`${window.location.origin}/share/${id}`);
    toast.success("Share snapshot created", { description: "Only the fields you selected are included." });
  };
  const copy = async () => { if (!created) return; await navigator.clipboard?.writeText(created); toast.success("Snapshot link copied"); };
  const exportSvg = () => downloadTextFile(`sprintly-${kind}-card.svg`, buildSvgCard(title, payload, fields), "image/svg+xml");
  return <div><PageHeader eyebrow="Social layer · user controlled" title="Create a share card" description="Choose exactly which aggregate fields appear. Generate is always explicit; nothing publishes automatically." action={<Link href="/app" className="inline-flex min-h-11 items-center gap-2 rounded-lg border border-white/[.08] px-4 text-sm text-[#cacaca]">Back to dashboard</Link>}/><div className="grid gap-3 xl:grid-cols-[.85fr_1.15fr]"><Panel className="p-5 sm:p-6"><div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-xl bg-[#f2f2f2]/10 text-[#d2d2d2]"><Sparkles className="size-5"/></div><div><h2 className="text-sm font-semibold">Customize {kind}</h2><p className="mt-1 text-xs text-[#7d7d7d]">{profile.displayName} · safe summary fields</p></div></div><div className="mt-6 space-y-2">{(Object.keys(SHARE_FIELD_LABELS) as ShareField[]).map((field) => <label key={field} className="flex min-h-12 cursor-pointer items-center gap-3 rounded-lg border border-white/[.07] bg-white/[.02] px-3 hover:bg-white/[.04]"><input type="checkbox" checked={fields.includes(field)} onChange={() => toggle(field)} className="size-4 accent-[#f2f2f2]"/><span className="text-xs">{SHARE_FIELD_LABELS[field]}</span><span className="ml-auto text-[10px] text-[#686868]">{field === "tokenUsage" || field === "terminalActivity" ? "optional" : "safe default"}</span></label>)}</div><div className="mt-6 rounded-xl border border-[#d0d0d0]/15 bg-[#d0d0d0]/[.04] p-4"><p className="text-sm font-medium text-[#c1c1c1]">Privacy guardrail</p><p className="mt-2 text-xs leading-5 text-[#858585]">Raw prompts, source code, file names, terminal output, and secrets are never part of the share model.</p></div><div className="mt-6 flex flex-col gap-2 sm:flex-row"><button onClick={generate} disabled={!fields.length} className="min-h-11 flex-1 rounded-lg bg-[#f2f2f2] text-[#0b0b0b] px-4 text-sm font-semibold disabled:opacity-40">Generate snapshot</button><button onClick={exportSvg} disabled={!fields.length} className="inline-flex min-h-11 items-center justify-center gap-2 rounded-lg border border-white/[.09] px-4 text-xs font-semibold text-[#cacaca] disabled:opacity-40"><Download className="size-4"/> Export SVG</button></div>{created && <div className="mt-5 rounded-xl border border-[#f2f2f2]/25 bg-[#f2f2f2]/[.06] p-4"><p className="text-xs font-medium">Snapshot URL</p><p className="mt-2 break-all font-mono text-[11px] text-[#d0d0d0]">{created}</p><div className="mt-3 flex gap-2"><button onClick={copy} className="min-h-9 rounded-lg bg-[#f2f2f2] text-[#0b0b0b] px-3 text-xs font-semibold">Copy link</button><Link href={created.replace(window.location.origin, "")} className="inline-flex min-h-9 items-center rounded-lg border border-white/[.09] px-3 text-xs text-[#cacaca]">Open snapshot</Link></div><p className="mt-3 text-[10px] leading-5 text-[#7d7d7d]">This development build stores snapshots in the browser’s local demo store. A production API will make these URLs portable across devices.</p></div>}</Panel><div><ShareCard title={title} payload={payload} fields={fields}/><Panel className="mt-3 p-5"><div className="flex items-center gap-3"><FileUp className="size-4 text-[#bdbdbd]"/><div><p className="text-sm font-medium">Made for sharing</p><p className="mt-1 text-xs leading-5 text-[#7d7d7d]">The SVG export is a social-friendly vector card. Share a session without exposing your full history.</p></div></div></Panel></div></div></div>;
}

export function PublicSnapshotPage() {
  const params = useParams<{ id?: string | string[] }>();
  const id = Array.isArray(params?.id) ? params.id[0] : params?.id;
  const [snapshot, setSnapshot] = useState<ShareSnapshot | null>(null);
  const [checked, setChecked] = useState(false);
  useEffect(() => { if (id) { const found = loadUserData(DEMO_USER.id).shares.find((share) => share.id === id) ?? null; setSnapshot(found); setChecked(true); } }, [id]);
  if (!checked) return <main className="grid min-h-dvh place-items-center bg-[#090909] text-sm text-[#8b8b8b]">Opening snapshot…</main>;
  if (!snapshot) return <main className="grid min-h-dvh place-items-center bg-[#090909] p-6 text-center"><div><p className="mono text-xs uppercase tracking-[.18em] text-[#f2f2f2]">Sprintly snapshot</p><h1 className="mt-4 text-2xl font-semibold">This snapshot is unavailable.</h1><p className="mt-2 text-sm text-[#7d7d7d]">It may have been deleted or created in another browser in this local demo.</p><Link href="/sign-in" className="mt-6 inline-flex min-h-11 items-center rounded-lg bg-[#f2f2f2] text-[#0b0b0b] px-4 text-sm font-semibold">Open Sprintly</Link></div></main>;
  return <main className="noise min-h-dvh bg-[#090909] px-4 py-8 sm:px-8"><div className="mx-auto max-w-xl"><div className="flex items-center justify-between"><Link href="/" className="text-sm font-semibold">sprintly</Link><Pill tone="gray"><Eye className="size-3"/> Public snapshot</Pill></div><div className="mt-10"><ShareCard title={snapshot.title} payload={snapshot.payload} fields={snapshot.selectedFields}/></div><p className="mt-5 text-center text-xs text-[#7d7d7d]">Only explicitly selected statistics are shown. This is not a complete developer profile.</p></div></main>;
}

function SettingToggle({ checked, onChange, label, description }: { checked: boolean; onChange: (value: boolean) => void; label: string; description: string }) {
  return <div className="flex gap-4 border-b border-white/[.06] py-4 last:border-0"><button type="button" onClick={() => onChange(!checked)} role="switch" aria-checked={checked} aria-label={label} className={`relative mt-0.5 h-6 w-11 shrink-0 rounded-full transition ${checked ? "bg-[#f2f2f2] text-[#0b0b0b]" : "bg-[#2d2d2d]"}`}><span className={`absolute top-1 size-4 rounded-full bg-white transition-transform ${checked ? "translate-x-6" : "translate-x-1"}`}/></button><div><p className="text-sm font-medium">{label}</p><p className="mt-1 text-xs leading-5 text-[#7d7d7d]">{description}</p></div></div>;
}

export function SettingsPage() {
  const router = useRouter();
  const { sessions, preferences, profile, updatePreferences, deleteCloudHistory, deleteAccountData } = useSprintly();
  const [section, setSection] = useState<"privacy" | "sync" | "data" | "account">("privacy");
  const [importOpen, setImportOpen] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState<"history" | "account" | null>(null);
  const records = recordsOf(sessions);
  const exportData = () => { downloadTextFile("sprintly-export.json", serializeSprintlyExport(records)); toast.success("Cloud data export prepared"); };
  const confirm = () => { if (confirmDelete === "history") { deleteCloudHistory(); toast.success("Cloud history deleted"); } if (confirmDelete === "account") { deleteAccountData(); clearAuthSession(); router.replace("/sign-in"); } setConfirmDelete(null); };
  const sections = [[ShieldCheck, "privacy", "Privacy Center"], [RefreshCw, "sync", "Sync scope"], [FileUp, "data", "Import & export"], [UserRound, "account", "Account"]] as const;
  return <div><PageHeader eyebrow="Privacy · data control" title="Privacy Center" description="See what is stored, what can be shared, and how to remove it. These controls are local-demo equivalents of the future authenticated account API."/><div className="grid gap-4 lg:grid-cols-[220px_1fr]"><Panel className="h-fit p-2">{sections.map(([Icon, value, label]) => <button key={value} onClick={() => setSection(value)} className={`flex min-h-11 w-full items-center gap-3 rounded-lg px-3 text-left text-sm ${section === value ? "bg-[#f2f2f2]/12 text-[#e6e6e6]" : "text-[#898989] hover:bg-white/[.04]"}`}><Icon className="size-4"/>{label}</button>)}</Panel><div>{section === "privacy" && <div className="space-y-3"><Panel className="p-5 sm:p-6"><div className="flex items-start gap-4"><div className="grid size-11 shrink-0 place-items-center rounded-xl bg-[#d0d0d0]/10 text-[#d0d0d0]"><ShieldCheck className="size-5"/></div><div><h2 className="text-base font-semibold">Your data, clearly scoped</h2><p className="mt-2 text-xs leading-5 text-[#858585]">{sessions.length} sessions stored online in this local demo. The extension is not connected continuously; only explicit imports are represented here.</p></div></div><div className="mt-6 rounded-xl border border-white/[.07] bg-black/10 px-4"><SettingToggle checked={preferences.profileVisibility === "public"} onChange={(value) => updatePreferences({ profileVisibility: value ? "public" : "private" })} label="Public developer profile" description="Expose your selected identity, coding mix, scores, streak, and achievements at your profile URL."/><SettingToggle checked={preferences.leaderboardOptIn} onChange={(value) => updatePreferences({ leaderboardOptIn: value })} label="Leaderboard participation" description="Share aggregate weekly packets only. Leave at any time to stop future submissions."/></div></Panel><Panel className="p-5 sm:p-6"><h2 className="text-sm font-semibold">Sharing safety</h2><div className="mt-5 grid gap-3 md:grid-cols-3">{[[HardDrive, "Stored sessions", "Aggregate contract records"], [Eye, "Public snapshots", "Only selected fields"], [LockKeyhole, "Never published", "Raw code, prompts, secrets"]].map(([Icon, title, description]) => { const C = Icon as typeof HardDrive; return <div key={String(title)} className="rounded-xl border border-white/[.07] bg-white/[.02] p-4"><C className="size-4 text-[#d6d6d6]"/><p className="mt-4 text-xs font-medium">{String(title)}</p><p className="mt-1 text-[11px] leading-5 text-[#7d7d7d]">{String(description)}</p></div>; })}</div></Panel></div>}{section === "sync" && <Panel className="p-5 sm:p-6"><h2 className="text-base font-semibold">Sync preference</h2><p className="mt-2 text-xs leading-5 text-[#858585]">This preference controls what the future extension handoff is allowed to submit.</p><div className="mt-6 space-y-2">{([["never", "Never sync", "Keep the website record empty unless you import a file."], ["selected", "Only sessions I choose", "Best default. Approve individual session exports."], ["completed", "Sync completed sessions", "Allow completed sessions after an explicit connection."], ["leaderboard", "Leaderboard stats only", "Submit aggregate ranking packets without full session history."]] as Array<[SyncPreference, string, string]>).map(([value, label, description]) => <button key={value} onClick={() => updatePreferences({ syncPreference: value })} className={`flex min-h-[76px] w-full items-start gap-3 rounded-xl border p-4 text-left ${preferences.syncPreference === value ? "border-[#f2f2f2]/45 bg-[#f2f2f2]/[.08]" : "border-white/[.07] bg-white/[.02]"}`}><span className={`mt-0.5 grid size-5 place-items-center rounded-full border ${preferences.syncPreference === value ? "border-[#f2f2f2]" : "border-[#5b5b5b]"}`}>{preferences.syncPreference === value && <span className="size-2.5 rounded-full bg-[#f2f2f2] text-[#0b0b0b]"/>}</span><span><span className="block text-sm font-medium">{label}</span><span className="mt-1 block text-xs leading-5 text-[#7d7d7d]">{description}</span></span></button>)}</div></Panel>}{section === "data" && <div className="space-y-3"><Panel className="p-5 sm:p-6"><div className="flex items-start gap-4"><div className="grid size-11 place-items-center rounded-xl bg-[#f2f2f2]/10 text-[#d2d2d2]"><FileUp className="size-5"/></div><div><h2 className="text-base font-semibold">Import Sprintly JSON</h2><p className="mt-2 text-xs leading-5 text-[#858585]">Validate schema version, ranges, timestamps, session IDs, and duplicates before import.</p></div></div><button onClick={() => setImportOpen(true)} className="mt-5 flex min-h-[100px] w-full flex-col items-center justify-center rounded-xl border border-dashed border-white/[.14] bg-white/[.02] text-sm text-[#aeaeae] hover:bg-white/[.035]"><FileJson className="mb-3 size-5 text-[#f2f2f2]"/>Choose .json export<span className="mt-1 text-[10px] text-[#757575]">Preview first · confirm second</span></button></Panel><Panel className="p-5 sm:p-6"><h2 className="text-sm font-semibold">Export cloud data</h2><p className="mt-2 text-xs leading-5 text-[#858585]">Download the validated session contract records currently stored for this account.</p><div className="mt-5 flex flex-wrap gap-2"><button onClick={exportData} className="inline-flex min-h-10 items-center gap-2 rounded-lg bg-[#f2f2f2] text-[#0b0b0b] px-3 text-xs font-semibold"><Download className="size-4"/> Export JSON</button><button onClick={() => setConfirmDelete("history")} className="inline-flex min-h-10 items-center gap-2 rounded-lg border border-[#b7b7b7]/25 px-3 text-xs font-semibold text-[#bbbbbb]"><X className="size-4"/> Delete cloud history</button></div></Panel></div>}{section === "account" && <div className="space-y-3"><Panel className="p-5 sm:p-6"><h2 className="text-base font-semibold">{profile.displayName}</h2><p className="mt-2 text-xs leading-5 text-[#858585]">{profile.handle} · {profile.city} · Demo Account</p><button onClick={() => { clearAuthSession(); router.replace("/sign-in"); }} className="mt-5 inline-flex min-h-10 items-center gap-2 rounded-lg border border-white/[.09] px-3 text-xs font-semibold text-[#cacaca]"><LogOut className="size-4"/> Sign out</button></Panel><Panel className="p-5 sm:p-6"><h2 className="text-sm font-semibold text-[#bbbbbb]">Delete account</h2><p className="mt-2 text-xs leading-5 text-[#848484]">Remove sessions, shares, preferences, and the local demo account session. This cannot be undone in this browser.</p><button onClick={() => setConfirmDelete("account")} className="mt-5 min-h-10 rounded-lg border border-[#b7b7b7]/25 px-3 text-xs font-semibold text-[#bbbbbb]">Delete account data</button></Panel></div>}</div></div><ImportFlow open={importOpen} onClose={() => setImportOpen(false)}/>{confirmDelete && <div className="fixed inset-0 z-[110] grid place-items-center bg-black/75 p-4 backdrop-blur-sm"><div role="dialog" aria-modal="true" className="w-full max-w-md rounded-2xl border border-white/10 bg-[#141414] p-5 shadow-2xl"><h2 className="text-lg font-semibold">{confirmDelete === "history" ? "Delete cloud history?" : "Delete account data?"}</h2><p className="mt-3 text-sm leading-6 text-[#8b8b8b]">{confirmDelete === "history" ? "All stored session records will be removed from this demo account." : "This removes the demo account data and signs you out."}</p><div className="mt-6 flex justify-end gap-2"><button onClick={() => setConfirmDelete(null)} className="min-h-11 rounded-lg border border-white/[.09] px-4 text-sm text-[#bdbdbd]">Cancel</button><button onClick={confirm} className="min-h-11 rounded-lg bg-[#b7b7b7] text-[#0b0b0b] px-4 text-sm font-semibold text-[#0b0b0b]">Confirm delete</button></div></div></div>}</div>;
}

export function PublicProfilePage() {
  const params = useParams<{ handle?: string | string[] }>();
  const handle = Array.isArray(params?.handle) ? params.handle[0] : params?.handle;
  const data = loadUserData(DEMO_USER.id);
  const [ready] = useState(true);
  if (!ready) return null;
  if (handle !== data.profile.handle || data.preferences.profileVisibility !== "public") return <main className="grid min-h-dvh place-items-center bg-[#090909] p-6 text-center"><div><p className="mono text-xs uppercase tracking-[.18em] text-[#f2f2f2]">Sprintly profile</p><h1 className="mt-4 text-2xl font-semibold">This profile is private.</h1><p className="mt-2 text-sm text-[#7d7d7d]">The developer has not opted into public profile statistics.</p><Link href="/sign-in" className="mt-6 inline-flex min-h-11 items-center rounded-lg bg-[#f2f2f2] text-[#0b0b0b] px-4 text-sm font-semibold">Open Sprintly</Link></div></main>;
  const records = data.sessions.map((item) => item.record);
  const aggregate = aggregateSessions(records);
  const streaks = getStreakStats(records);
  const achievements = computeAchievements(records, streaks).filter((achievement) => achievement.unlocked);
  return <main className="noise min-h-dvh bg-[#090909] px-4 py-8 sm:px-8"><div className="mx-auto max-w-3xl"><div className="flex items-center justify-between"><Link href="/" className="text-sm font-semibold">sprintly</Link><Pill tone="green"><Globe2 className="size-3"/> Public profile</Pill></div><Panel className="mt-10 p-6 sm:p-8"><div className="flex flex-col gap-6 sm:flex-row sm:items-center"><div className={`grid size-24 shrink-0 place-items-center rounded-[28px] bg-gradient-to-br ${avatarStyle(aggregate.archetype, aggregate.traits)} text-2xl font-semibold`}>{initials(data.profile.displayName)}</div><div><p className="text-2xl font-semibold">{data.profile.displayName}</p><p className="mt-1 text-sm text-[#8b8b8b]">@{data.profile.handle} · {data.profile.city}</p><p className="mt-4 text-sm text-[#bdbdbd]">{aggregate.archetype}</p></div></div><div className="mt-8 grid grid-cols-2 gap-3 sm:grid-cols-4">{[["Manual", `${aggregate.coding.manualPercent}%`], ["AI-assisted", `${aggregate.coding.aiAssistedPercent}%`], ["Focus", aggregate.scores.focus], ["Dev Score", buildLeaderboardPacket(records, data.profile.country).devScore], ["Recovery", `${aggregate.reliability.recoveryRate}%`], ["Streak", `${streaks.current} days`], ["Sessions", records.length], ["Achievements", achievements.length]].map(([label, value]) => <div key={String(label)} className="rounded-xl bg-white/[.025] p-4"><p className="mono text-xl font-semibold">{String(value)}</p><p className="mt-1 text-[10px] text-[#7a7a7a]">{String(label)}</p></div>)}</div><div className="mt-8 flex flex-wrap gap-2">{aggregate.traits.map((trait) => <Pill key={trait} tone="gray">{trait}</Pill>)}</div></Panel><p className="mt-5 text-center text-xs text-[#7d7d7d]">Public summary only · raw prompts, source code, terminal output, and complete history are private.</p></div></main>;
}
